import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const OUTPUT = path.join(ROOT, "lib", "db", "database.types.ts");

const header = `/**
 * Generated by \`npm run db:types\` from the applied local schema.
 * Do not edit by hand. Treat supabase/migrations as the source of truth.
 */

`;

const result = spawnSync(
  "npx",
  [
    "supabase",
    "gen",
    "types",
    "typescript",
    "--local",
    "--schema",
    "public",
    "--log-level",
    "error",
  ],
  {
    cwd: ROOT,
    encoding: "utf8",
    shell: true,
  },
);

if (result.status !== 0) {
  process.stderr.write(result.stderr || result.stdout || "supabase gen types failed\n");
  process.exit(result.status ?? 1);
}

const raw = (result.stdout || "").replace(/\r\n/g, "\n");
const start = raw.search(/^export type Json/m);
if (start < 0) {
  process.stderr.write("supabase gen types did not return a Database type.\n");
  process.exit(1);
}

let body = raw.slice(start);
const end = body.lastIndexOf("} as const");
if (end < 0) {
  process.stderr.write("supabase gen types output was truncated.\n");
  process.exit(1);
}
body = body.slice(0, end + "} as const".length).trim();

if (!body.includes("export type Database")) {
  process.stderr.write("supabase gen types did not return a Database type.\n");
  process.exit(1);
}

fs.mkdirSync(path.dirname(OUTPUT), { recursive: true });
fs.writeFileSync(OUTPUT, `${header}${body}\n`, "utf8");
console.log(`Wrote ${path.relative(ROOT, OUTPUT)}`);
